WoWFA_Data[385952] = "با سپر خود به سمت یک دشمن Charge می‌کنید، Shield Block به‌دست می‌آورید و به آن $385954s1 آسیب Physical و به تمام دشمنان در فاصلهٔ 10 یارد $385954s2 آسیب Physical وارد می‌کنید.\n\nهمچنین هدف اصلی را برای 4 ثانیه استان می‌کند.\n\n|cFFFFFFFF20 Rage تولید می‌کند.|r"
WoWFA_Data[386011] = "شانس بلاک را به‌اندازهٔ 8% و مقدار بلاک شما را به‌اندازهٔ 16% افزایش می‌دهد."
WoWFA_Data[386027] = "Shield Block 1 ثانیه بیشتر دوام می‌آورد."
WoWFA_Data[386030] = "استفاده از Shield Slam، آسیب Shield Slam را برای 16 ثانیه به‌اندازهٔ 10% و مقدار بلاک سپر شما را به‌اندازهٔ 5% افزایش می‌دهد. تا 3 بار روی هم قرار می‌گیرد."
WoWFA_Data[386071] = "تمام دشمنان در فاصلهٔ 14 یارد را برای 6 ثانیه تانت می‌کند تا به شما حمله کنند، تمام کست‌های اسپل در فاصلهٔ 14 یارد را قطع می‌کند و جلوی کست شدن هر اسپلی از آن school را برای 6 ثانیه می‌گیرد. تهدید ایجادشدهٔ شما علیه هدف را به‌اندازهٔ 800% افزایش می‌دهد."
WoWFA_En[386164] = "A balanced combat state that increases the critical strike chance of your abilities by $s1%$?a1280961[, the critical strike damage of your abilities by $s4%,][] and reduces the duration of movement impairing effects by $s2%. \n\nLasts until canceled."
WoWFA_Data[386164] = "حالتی متعادل در نبرد که شانس Critical Strike توانایی‌های شما را به‌اندازهٔ 3% افزایش می‌دهد$?a1280961[، آسیب Critical Strike توانایی‌های شما را به‌اندازهٔ 3% افزایش می‌دهد،][] و مدت اثرات مختل‌کنندهٔ حرکت را به‌اندازهٔ 10% کاهش می‌دهد. \n\nتا زمانی که لغو شود ادامه دارد."
WoWFA_En[386196] = "An aggressive combat state that increases the damage of your auto-attacks by $s1%$?a1280961[, your auto-attack speed by $s6%,][] and reduces the duration of Fear, Sap and Incapacitate effects on you by $s2%.\n\nLasts until canceled."
WoWFA_Data[386196] = "حالتی تهاجمی در نبرد که آسیب حملات خودکار شما را به‌اندازهٔ 15% افزایش می‌دهد$?a1280961[، سرعت حملهٔ خودکار شما را به‌اندازهٔ 3% افزایش می‌دهد،][] و مدت اثرات Fear، Sap و Incapacitate روی شما را به‌اندازهٔ 10% کاهش می‌دهد.\n\nتا زمانی که لغو شود ادامه دارد."
WoWFA_En[386208] = "A defensive combat state that reduces all damage you take by $s1%$?a452494[ and all magic damage you take by an additional $s3%][]$?a137048[][ and all damage you deal by $s2%].$?a1280961[\n\nWhen an attack deals $s5% or more of your maximum health in damage, that damage is reduced by $s6%.][]\n\nLasts until canceled."
WoWFA_Data[386208] = "حالتی دفاعی در نبرد که تمام آسیب دریافتی شما را به‌اندازهٔ 15% کاهش می‌دهد$?a452494[ و آسیب Magic دریافتی شما را به‌طور اضافی به‌اندازهٔ $s3% کاهش می‌دهد][]$?a137048[][ و تمام آسیبی که وارد می‌کنید را به‌اندازهٔ 10% کاهش می‌دهد].$?a1280961[\n\nوقتی حمله‌ای به‌اندازهٔ 20% یا بیشتر از حداکثر سلامتی شما آسیب وارد کند، آن آسیب به‌اندازهٔ 15% کاهش می‌یابد.][]\n\nتا زمانی که لغو شود ادامه دارد."
WoWFA_Data[386394] = "وقتی سلامتی شما به زیر 30% برسد، برای 8 ثانیه به‌اندازهٔ 80% آسیب کمتری دریافت می‌کنید و شفایی که دریافت می‌کنید به‌اندازهٔ 100% افزایش می‌یابد.\n\nنمی‌تواند بیشتر از هر 3 دقیقه یک‌بار رخ دهد."
WoWFA_Data[386477] = "هر 250 Rage که مصرف می‌کنید یک Violent Outburst فعال می‌کند که باعث می‌شود Shield Slam بعدی شما به‌اندازهٔ 200% آسیب بیشتری وارد کند، 50% Rage بیشتری تولید کند و Ignore Pain بدهد."
WoWFA_En[386628] = "Every $s1 strikes of Bladestorm, you automatically cast a $?c1[Mortal Strike][Bloodthirst] at your target or random nearby enemy, dealing $s2% of normal damage.\n"
WoWFA_Data[386628] = "هر 2 ضربهٔ Bladestorm، به‌طور خودکار یک $?c1[Mortal Strike][Bloodthirst] به هدف یا یک دشمن نزدیک تصادفی کست می‌کنید و به‌اندازهٔ 100% آسیب عادی وارد می‌کنید."
WoWFA_Data[386630] = "Overpower 35% شانس دارد کول‌داون Mortal Strike را بازنشانی کند و هزینهٔ Mortal Strike بعدی شما را به‌اندازهٔ 33% کاهش دهد."
WoWFA_Data[386634] = "Execute آسیب Mortal Strike بعدی شما را به‌اندازهٔ 35% افزایش می‌دهد و تا 2 بار روی هم قرار می‌گیرد."
WoWFA_Data[389306] = "شانس Critical Strike Execute به‌اندازهٔ 5% افزایش می‌یابد و Execute بلافاصله 10% اضافی از Rage مصرف‌شده را بازمی‌گرداند."
WoWFA_En[391271] = "Cooldown of $?c1[Die By the Sword]?c2[Enraged Regeneration][Shield Wall], Intervene, $?c3[][Interpose, ]Spell Reflection, Storm Bolt, and Pummel reduced by $s1%.\n\nSuccessfully interrupting an enemy increases the damage you deal to them by $383116s2% for $383116d."
WoWFA_Data[391271] = "کول‌داون $?c1[Die By the Sword]?c2[Enraged Regeneration][Shield Wall]، Intervene، $?c3[][Interpose، ]Spell Reflection، Storm Bolt و Pummel به‌اندازهٔ 10% کاهش می‌یابد.\n\nقطع موفق یک دشمن، آسیبی که به او وارد می‌کنید را برای 10 ثانیه به‌اندازهٔ 5% افزایش می‌دهد."
WoWFA_Data[392777] = "شانس Critical Strike به‌اندازهٔ 1% و آسیب Critical Strike Execute به‌اندازهٔ 5% افزایش می‌یابد."
WoWFA_En[392792] = "$?c1[Mortal Strike and Cleave have]?c2[Rampage has][Revenge has] a $h% chance to immediately refund $?c1[$s1]?c2[$s2][$s3]% of the Rage spent."
WoWFA_Data[392792] = "$?c1[Mortal Strike و Cleave]?c2[Rampage][Revenge] 20% شانس دارد که بلافاصله $?c1[10]?c2[10][50]% از Rage مصرف‌شده را بازگرداند."
WoWFA_Data[392931] = "در حالی که Enraged هستید، Bloodthirst و Raging Blow به‌اندازهٔ 5% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[392936] = "Raging Blow به‌اندازهٔ 15% آسیب بیشتری وارد می‌کند و در حالی که Enraged هستید، Raging Blow 10% شانس بیشتری دارد که کول‌داون خودش را بلافاصله بازنشانی کند."
WoWFA_Data[393950] = "Raging Blow آسیب Bloodthirst بعدی شما را به‌اندازهٔ 5% افزایش می‌دهد و تا 5 بار روی هم قرار می‌گیرد."
WoWFA_Data[394311] = "Devastate به‌اندازهٔ 20% آسیب بیشتری وارد می‌کند و 2 Rage تولید می‌کند.\n\nDevastator به‌اندازهٔ 10% آسیب بیشتری وارد می‌کند و 2 Rage تولید می‌کند."
WoWFA_En[396749] = "Activating Recklessness generates ${$s1/10} Rage and while Recklessness is active, Raging Blow and Bloodthirst are upgraded to Crushing Blow and Bloodbath.\n\n$@spellicon335097 $@spellname335097\nDeals increased damage and deals $1719s13% additional critical strike damage.\n\n$@spellicon335096 $@spellname335096\nDeals increased damage and wounds the target to suffer $113344o1 Bleed damage over $113344d. Using Bloodbath on a target affected by Bloodbath extends the bleed by $113344d."
WoWFA_Data[396749] = "فعال کردن Recklessness، 50 Rage تولید می‌کند و وقتی Recklessness فعال است، Raging Blow و Bloodthirst به Crushing Blow و Bloodbath ارتقا می‌یابند.\n\n Crushing Blow\nآسیب بیشتری وارد می‌کند و به‌اندازهٔ 20% آسیب Critical Strike اضافی وارد می‌کند.\n\n Bloodbath\nآسیب بیشتری وارد می‌کند و هدف را زخمی می‌کند تا طی 6 ثانیه، $113344o1 آسیب Bleed دریافت کند. استفاده از Bloodbath روی هدفی که تحت تأثیر Bloodbath است، خونریزی را به‌اندازهٔ 6 ثانیه تمدید می‌کند."
WoWFA_Data[397103] = "Shield Wall 1 شارژ اضافی به‌دست می‌آورد و کول‌داون آن 60 ثانیه کاهش می‌یابد."
WoWFA_Data[400205] = "Overpower به اهدافی که زیر 35% سلامتی هستند، به‌اندازهٔ 15% آسیب اضافی وارد می‌کند."
WoWFA_Data[400803] = "آسیب Overpower و Slam به‌اندازهٔ 5% و آسیب Critical Strike آن‌ها به‌اندازهٔ 5% افزایش می‌یابد.\nشانس Critical Strike Slam و Overpower به‌اندازهٔ 5% افزایش می‌یابد."
WoWFA_Data[424742] = "توانایی‌های Shout شما اثرات اضافی دارند.\n\n Battle Shout:\nمقدار 3% Attack Power اضافی به شما می‌دهد.\n\n Rallying Cry:\nمقدار 2% سلامتی اضافی می‌دهد و مدت آن 3 ثانیه افزایش می‌یابد.\n\n Piercing Howl:\nشعاع به‌اندازهٔ 100% افزایش می‌یابد\n\n Berserker Shout:\nشعاع به‌اندازهٔ 100% افزایش می‌یابد.\n\n Intimidating Shout:\nکول‌داون 15 ثانیه کاهش می‌یابد."
WoWFA_En[429634] = "Colossal Might increases damage dealt by your next Demolish by $440989s1%, stacking up to $440989u times.\n\n$?c1[Mortal Strike][Shield Slam] grants a stack of Colossal Might and $?c1[Cleave][Revenge] grants a stack of Colossal Might when it strikes $s1 or more targets."
WoWFA_Data[429634] = "Colossal Might آسیب Demolish بعدی شما را به‌اندازهٔ 5% افزایش می‌دهد و تا 5 بار روی هم قرار می‌گیرد.\n\n$?c1[Mortal Strike][Shield Slam] یک استک Colossal Might می‌دهد و $?c1[Cleave][Revenge] وقتی به 3 هدف یا بیشتر ضربه بزند، یک استک Colossal Might می‌دهد."
WoWFA_Data[429636] = "دشمنان تحت تأثیر Demolish بر اساس تعداد استک‌های Colossal Might که Demolish مصرف می‌کند، برای 10 ثانیه حداکثر 10% آسیب بیشتری از شما دریافت می‌کنند و حداکثر 20% آسیب کمتری به شما وارد می‌کنند.\n\nColossal Might تا 10 بار روی هم قرار می‌گیرد."
WoWFA_En[429637] = "Shockwave$?c1[, Cleave,][] and $?c1[Whirlwind][Revenge] deal $s1% more damage per target affected up to $s2."
WoWFA_Data[429637] = "Shockwave$?c1[، Cleave،][] و $?c1[Whirlwind][Revenge] به‌ازای هر هدف تحت تأثیر، به‌اندازهٔ 5% آسیب بیشتری وارد می‌کنند، حداکثر تا 5."
WoWFA_Data[429638] = "آسیب Critical Strike توانایی‌های شما به‌اندازهٔ 10% افزایش می‌یابد و مقدار آسیبی که بلاک‌های Critical Strike شما بلاک می‌کنند به‌اندازهٔ 20% افزایش می‌یابد."
WoWFA_Data[429639] = "مدت استان Shockwave 1 ثانیه افزایش می‌یابد و پس از پایان استان، سرعت حرکت دشمنان تحت تأثیر را برای 3 ثانیه به‌اندازهٔ 40% کاهش می‌دهد."
WoWFA_En[429641] = "Colossal Might increases the damage of your $?c1[Overpower][Revenge] and Execute by $?c1[$440989s3][$440989s4]% per stack."
WoWFA_Data[429641] = "Colossal Might آسیب $?c1[Overpower][Revenge] و Execute شما را به‌ازای هر استک به‌اندازهٔ $?c1[3][3]% افزایش می‌دهد."
WoWFA_Data[429642] = "به‌اندازهٔ 5% آسیب بیشتری وارد می‌کنید و به‌اندازهٔ 5% آسیب کمتری دریافت می‌کنید.\n\nاندازه به‌اندازهٔ 5% افزایش می‌یابد."
WoWFA_Data[429644] = "آسیبی که هر بار استفاده از Ignore Pain پیشگیری می‌کند، به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_En[429647] = "$?c1[Mortal Strike and Slam damage increased by $s1%.\n\nCleave and Whirlwind damage increased by $s2%][Shield Slam damage increased by $s3%.\n\nRevenge and Thunder Clap damage increased by $s4%].$?c3[\n\nShield Slam generates an additional ${$s5/10} Rage. Revenge and Execute Rage cost reduced by ${$s6/-10}.][]"
WoWFA_Data[429647] = "$?c1[آسیب Mortal Strike و Slam به‌اندازهٔ 25% افزایش می‌یابد.\n\nآسیب Cleave و Whirlwind به‌اندازهٔ 15% افزایش می‌یابد][آسیب Shield Slam به‌اندازهٔ 25% افزایش می‌یابد.\n\nآسیب Revenge و Thunder Clap به‌اندازهٔ 15% افزایش می‌یابد].$?c3[\n\nShield Slam 4 Rage اضافی تولید می‌کند. هزینهٔ Rage Revenge و Execute به‌اندازهٔ 10 کاهش می‌یابد.][]"
WoWFA_En[431548] = "$?c1[Mortal Strike][Shield Slam] critical strikes grant an additional stack of Colossal Might."
WoWFA_Data[431548] = "Critical Strike زدن $?c1[Mortal Strike][Shield Slam]، یک استک اضافی Colossal Might می‌دهد."
WoWFA_En[434969] = "Damaging enemies with Thunder Clap, $?a137048[Revenge, ][Raging Blow, ]or Execute has a $s1% chance to also strike one with a lightning bolt, dealing $435791s1 Nature damage$?s436152[ and generating ${$436152s3/10} Rage][].\n\nLightning Strikes occur $s2% more often during Avatar."
WoWFA_Data[434969] = "آسیب زدن به دشمنان با Thunder Clap، $?a137048[Revenge، ][Raging Blow، ]یا Execute، 25% شانس دارد که یکی را نیز با صاعقه اصابت دهد و $435791s1 آسیب Nature وارد کند$?s436152[ و ${$436152s3/10} Rage تولید کند][].\n\nLightning Strikes در طول Avatar، 30% بیشتر رخ می‌دهند."
WoWFA_En[434970] = "Stamina increased by $s1%.\n\n$?s202168[Impending Victory][Victory Rush] increases your maximum health by $437152s3% for $437152d. When this health increase expires, you heal for any amount of the original $?s202168[Impending Victory][Victory Rush] that healed you in excess of your full health."
WoWFA_Data[434970] = "Stamina به‌اندازهٔ 5% افزایش می‌یابد.\n\n$?s202168[Impending Victory][Victory Rush] حداکثر سلامتی شما را برای 5 ثانیه به‌اندازهٔ 10% افزایش می‌دهد. وقتی این افزایش سلامتی منقضی شود، به‌اندازهٔ هر مقداری از شفای $?s202168[Impending Victory][Victory Rush] اصلی که بیش از سلامتی کامل شما بود، شفا می‌یابید."
WoWFA_En[435607] = "Shield Slam and Bloodthirst have a $s1% chance to grant you Thunder Blast, stacking up to 2 charges.\n\n$@spellicon435222|cFFFFFFFF$@spellname435222|r\nYour next Thunder Clap becomes a Thunder Blast that deals $435222s1 Stormstrike damage and generates ${$435222s4/10} Rage."
WoWFA_Data[435607] = "Shield Slam و Bloodthirst 35% شانس دارند Thunder Blast به شما بدهند و تا 2 شارژ روی هم قرار می‌گیرند.\n\n|cFFFFFFFFThunder Blast|r\nThunder Clap بعدی شما به Thunder Blast تبدیل می‌شود که $435222s1 آسیب Stormstrike وارد می‌کند و 2 Rage تولید می‌کند."
WoWFA_En[436148] = "Lightning Strikes also deal $460670s1 Nature damage to enemies near their target. Damage reduced beyond $460670s2 targets."
WoWFA_Data[436148] = "Lightning Strikes همچنین به دشمنان نزدیک هدفشان، $460670s1 آسیب Nature وارد می‌کنند. آسیب پس از 5 هدف کاهش می‌یابد."
WoWFA_En[436152] = "Lightning Strikes generate ${$s1/10} Rage.\n\n$?a137048[Revenge][Raging Blow] and Execute damage increased by $s2%."
WoWFA_Data[436152] = "Lightning Strikes 3 Rage تولید می‌کنند.\n\nآسیب $?a137048[Revenge][Raging Blow] و Execute به‌اندازهٔ 25% افزایش می‌یابد."
WoWFA_Data[436162] = "Storm Bolt همچنین به 2 هدف نزدیک اضافی ضربه می‌زند و آن‌ها را برای 2 ثانیه استان می‌کند، اما کول‌داون آن 10 ثانیه افزایش می‌یابد."
WoWFA_Data[436201] = "حملات شما 30% بیشتر Lightning Strikes فعال می‌کنند."
WoWFA_En[436358] = "Unleash a series of precise and powerful strikes against your target, dealing ${$440884s1+$440886s1+$440888s1} damage to it, and $440888s1 damage to enemies within $440888A1 yds of it. Deals reduced damage beyond $s1 targets.\n\nWhile channeling Demolish, you take $s4% less damage and are immune to stuns, knockbacks, and forced movement effects.\n\nYou can block, parry, dodge, and use certain defensive abilities while channeling Demolish."
WoWFA_Data[436358] = "مجموعه‌ای از ضربه‌های دقیق و قدرتمند را به هدف شما آزاد می‌کند، به آن ${$440884s1+$440886s1+$440888s1} آسیب و به دشمنان در فاصلهٔ 10 یارد از آن، $440888s1 آسیب وارد می‌کند. آسیب پس از 8 هدف کاهش می‌یابد.\n\nدر حالی که Demolish را کانال می‌کنید، 10% آسیب کمتری دریافت می‌کنید و در برابر استان، Knockback و اثرات جابه‌جایی اجباری ایمن هستید.\n\nدر حالی که Demolish را کانال می‌کنید، می‌توانید بلاک، پری و داج کنید و از برخی توانایی‌های دفاعی استفاده کنید."
WoWFA_En[436707] = "Stormstrike or Nature damage your abilities deal is increased by $s1%. Stormstrike damage ignores Armor.\n\nThunder Clap damage increased by $s4%$?a137050[, no longer costs Rage, and now generates ${$s5/10} Rage][].$?a137050[\n\nImproved Whirlwind, Meat Cleaver, Storm of Blood, and Barbaric Training affect Thunder Clap in addition to Whirlwind.][]"
WoWFA_Data[436707] = "آسیب Stormstrike یا Nature که توانایی‌های شما وارد می‌کنند به‌اندازهٔ 5% افزایش می‌یابد. آسیب Stormstrike Armor را نادیده می‌گیرد.\n\nآسیب Thunder Clap به‌اندازهٔ 10% افزایش می‌یابد$?a137050[، دیگر Rage مصرف نمی‌کند و اکنون 8 Rage تولید می‌کند][].$?a137050[\n\nImproved Whirlwind، Meat Cleaver، Storm of Blood و Barbaric Training علاوه بر Whirlwind، روی Thunder Clap نیز اثر می‌گذارند.][]"
