WoWFA_Data[1270718] = "مدت Executioner 6 ثانیه افزایش می‌یابد."
WoWFA_Data[1270723] = "آسیب Lightning Strike به‌اندازهٔ 10% و آسیب Critical Strike آن به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[1270724] = "در طول Avatar، Thunder Blast مدت Avatar را 2 ثانیه تمدید می‌کند."
WoWFA_Data[1271925] = "کول‌داون Berserker Rage به‌اندازهٔ 50% کاهش می‌یابد و Berserker Rage تمام اثرات کاهندهٔ سرعت حرکت را حذف می‌کند."
WoWFA_Data[1271926] = "شفای دریافتی به‌اندازهٔ 3% و تمام شفای خود به‌طور اضافی به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_Data[1271948] = "برد توانایی‌های پرتابی شما 5 یارد افزایش می‌یابد.\n\nآسیب Champion's Spear، Shattering Throw و Wrecking Throw به‌اندازهٔ 20% افزایش می‌یابد.\n\nShattering Throw و Wrecking Throw غیربازیکنان را برای 3 ثانیه سایلنت می‌کنند."
WoWFA_Data[1273062] = "Overpower و Slam آسیب Mortal Strike بعدی شما را به‌اندازهٔ 5% افزایش می‌دهند و تا 3 بار روی هم قرار می‌گیرند."
WoWFA_Data[1273075] = "Cleave و Whirlwind به اهدافی که زیر 35% سلامتی هستند، به‌اندازهٔ 20% آسیب اضافی وارد می‌کنند."
WoWFA_En[1277297] = "Fight through the pain, ignoring $s2% of damage taken for $d or until ${($s1)*(1+$@versadmg)} damage has been prevented."
WoWFA_Data[1277297] = "از میان درد می‌جنگید و برای 12 ثانیه یا تا زمانی که ${($s1)*(1+$@versadmg)} آسیب پیشگیری شود، 50% از آسیب دریافتی را نادیده می‌گیرید."
WoWFA_En[1280961] = "Your stances have additional effects.\n\n$?c1|c3[$@spellicon386164 $@spellname386164\nIncreases the critical strike damage of your abilities by $386164s4%.][$@spellicon386196 $@spellname386196\nIncreases your auto-attack speed by $386196s6%.]\n\n$@spellicon386208 $@spellname386208\nWhen an attack deals $386208s5% or more of your maximum health in damage, that damage is reduced by $386208s6%."
WoWFA_Data[1280961] = "وضعیت‌های Stance شما اثرات اضافی دارند.\n\n$?c1|c3[ Battle Stance\nآسیب Critical Strike توانایی‌های شما را به‌اندازهٔ 3% افزایش می‌دهد.][ Berserker Stance\nسرعت حملهٔ خودکار شما را به‌اندازهٔ 3% افزایش می‌دهد.]\n\n Defensive Stance\nوقتی حمله‌ای به‌اندازهٔ 20% یا بیشتر از حداکثر سلامتی شما آسیب وارد کند، آن آسیب به‌اندازهٔ 15% کاهش می‌یابد."
WoWFA_En[1299025] = "Whirlwind $?a436707[and Thunder Clap ][]affects all targets with Rend, causing them to Bleed for $388539o1 damage over $388539d.\n"
WoWFA_Data[1299025] = "Whirlwind $?a436707[و Thunder Clap ][]تمام اهدافی که Rend دارند را تحت تأثیر قرار می‌دهد و باعث می‌شود طی 15 ثانیه، $388539o1 آسیب Bleed وارد کنند."
WoWFA_Data[1300463] = "Whirlwind وقتی فقط به یک هدف اصابت کند، به‌اندازهٔ 50% آسیب اضافی وارد می‌کند."
